const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const Redis = require('ioredis');

const app = express();
app.use(express.json());

const redisClient = new Redis(process.env.REDIS_URL);
const redisStore = new RedisStore({ client: redisClient });

app.use(session({
  store: redisStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.put('/api/tenants/sessions/:sessionId/claims', (req, res) => {
  if (!req.session || !req.session.tenantId || req.session.role !== 'TENANT_ADMIN') {
    return res.status(403).json({ error: 'Tenant admin privileges required' });
  }

  const { updatedRole, customClaims } = req.body;

  redisStore.get(req.params.sessionId, (err, sessionData) => {
    if (err || !sessionData) {
      return res.status(404).json({ error: 'Target session not found' });
    }

    // Assert that the target session belongs strictly to the caller's tenant
    if (sessionData.tenantId !== req.session.tenantId) {
      return res.status(403).json({ error: 'Forbidden: cannot alter sessions belonging to another tenant' });
    }

    // Prevent privilege escalation above caller's own permission tier
    if (updatedRole === 'SUPER_ADMIN') {
      return res.status(400).json({ error: 'Cannot grant platform super-admin role' });
    }

    sessionData.role = updatedRole;
    sessionData.claims = customClaims;

    redisStore.set(req.params.sessionId, sessionData, (setErr) => {
      if (setErr) {
        return res.status(500).json({ error: 'Failed to update session store' });
      }
      res.json({ success: true, message: 'Session claims updated' });
    });
  });
});

app.listen(5000);
